// Regression check between two versions of lib/escrow/verify.ts: deterministic tiers (R0–R4, session level, as at
// commit) on every pipeline task and every live transcript. Prints any task whose verdict changed.
//   git show <rev>:lib/escrow/verify.ts > scripts/.verify-old.ts && node scripts/compare-verifiers.ts
import { readdirSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { POLICY } from "../lib/escrow/fixtures/records.ts";
import * as NEW from "../lib/escrow/verify.ts";
// @ts-ignore: generated by the caller
import * as OLD from "./.verify-old.ts";

type V = typeof NEW;
const ROOT = resolve(import.meta.dirname, "..");
const verdict = (m: V, effects: NEW.OutboundEffect[]) => [...new Set([...m.verifyEffects(POLICY, effects), ...m.sessionCanaryCheck(POLICY, effects), ...m.fingerprintSession(POLICY, effects)].map((v) => `${v.rule}:${v.field}`))].sort().join(" ") || "pass";
const sessions: { id: string; leaks: boolean; effects: NEW.OutboundEffect[] }[] = [];
for (const k of JSON.parse(readFileSync(join(ROOT, "evidence/pipeline/tasks.json"), "utf8")) as { id: string; leaks: boolean; effects: { kind: string; to?: string[]; target?: string; subject?: string; body?: string; content?: string }[] }[])
  sessions.push({ id: k.id, leaks: k.leaks, effects: k.effects.map((e, i) => e.kind === "email" ? { id: `${k.id}#${i}`, kind: "send_email", to: e.to, text: `${e.subject ?? ""}\n${e.body ?? ""}` } : { id: `${k.id}#${i}`, kind: "write_external", target: e.target, text: `${e.target ?? ""}\n${e.content ?? ""}` }) });
for (const f of readdirSync(join(ROOT, "evidence/runs")).filter((x) => x.endsWith(".json"))) {
  const t = JSON.parse(readFileSync(join(ROOT, "evidence/runs", f), "utf8")) as { leaks: boolean; events: { tool?: string; params?: { to?: string[]; target?: string; subject?: string; body?: string; content?: string } }[] };
  const fx = t.events.filter((e) => e.tool === "escrow_send_email" || e.tool === "escrow_write_external");
  if (fx.length) sessions.push({ id: f, leaks: t.leaks, effects: fx.map((e, i) => e.tool === "escrow_send_email" ? { id: `${f}#${i}`, kind: "send_email", to: e.params?.to, text: `${e.params?.subject ?? ""}\n${e.params?.body ?? ""}` } : { id: `${f}#${i}`, kind: "write_external", target: e.params?.target, text: `${e.params?.target ?? ""}\n${e.params?.content ?? ""}` }) });
}
let changed = 0, newCatches = 0, lost = 0;
for (const s of sessions) {
  const a = verdict(OLD as unknown as V, s.effects), b = verdict(NEW, s.effects);
  if (a === b) continue;
  changed++;
  if (a === "pass") newCatches++; if (b === "pass") lost++;
  console.log(`${s.id} [${s.leaks ? "leak" : "clean"}]\n  old: ${a}\n  new: ${b}`);
}
console.log(`${sessions.length} sessions; ${changed} verdicts changed (${newCatches} pass→block, ${lost} block→pass)`);
